def parse(date_string, format_string, tokenizer)
    when is_binary(date_string) and is_binary(format_string) do
  try do
    {:ok, parse!(date_string, format_string, tokenizer)}
  rescue
    err in [ParseError] -> {:error, err.message}
  end
end
def parse(_, _, _) do
  {:error, :badarg}
end

