def ping(conn, timeout \\ 5000)
    when (is_integer(timeout) and timeout >= 0) or timeout == :infinity do
  :gen_statem.call(conn, :ping, timeout)
catch
  :exit, {:timeout, _} -> {:error, %ConnectionError{reason: :timeout}}
end
